//! Replays `fixtures/vcs-process.jsonl`, generated by `rust/tools/generate_vcs_process_fixtures.mjs`
//! from the original VcsProcess.ts with a scripted ProcessRunner.
use std::{
    sync::{
        Arc,
        atomic::{AtomicUsize, Ordering},
    },
    time::Duration,
};

use futures_util::future::BoxFuture;
use serde_json::{Map, Value, json};
use t3_vcs::{
    VcsError, VcsProcess, VcsProcessInput,
    error::{OutputStream, ReadStream},
    process::{
        CHECKPOINT_CAPTURE_OPERATION, ProcessRunError, ProcessRunInput, ProcessRunOutput,
        ProcessRunner,
    },
};

type Script = dyn Fn(usize) -> Result<ProcessRunOutput, ProcessRunError> + Send + Sync;

struct Scripted {
    attempts: AtomicUsize,
    script: Box<Script>,
}

impl ProcessRunner for Scripted {
    fn run(&self, _: ProcessRunInput) -> BoxFuture<'_, Result<ProcessRunOutput, ProcessRunError>> {
        let attempt = self.attempts.fetch_add(1, Ordering::SeqCst) + 1;
        Box::pin(async move { (self.script)(attempt) })
    }
}

fn process_with(
    script: impl Fn(usize) -> Result<ProcessRunOutput, ProcessRunError> + Send + Sync + 'static,
) -> (VcsProcess, Arc<Scripted>) {
    let runner = Arc::new(Scripted {
        attempts: AtomicUsize::new(0),
        script: Box::new(script),
    });
    (
        VcsProcess::with_runner(runner.clone()).with_retry_delay(Duration::ZERO),
        runner,
    )
}

fn input(row: &Value) -> VcsProcessInput {
    let mut input = VcsProcessInput::new(
        row.get("operation")
            .and_then(Value::as_str)
            .unwrap_or("test.process-boundary"),
        row.get("command").and_then(Value::as_str).unwrap_or("git"),
        ["status", "--short"],
        "/workspace",
    );
    input.allow_non_zero_exit = row["allowNonZeroExit"].as_bool().unwrap_or(false);
    if row["streaming"].as_bool().unwrap_or(false) {
        input.on_stdout_chunk = Some(Arc::new(|_| {}));
    }
    input
}

fn put(fields: &mut Map<String, Value>, key: &str, value: impl Into<Value>) {
    fields.insert(key.into(), value.into());
}

/// The fields the fixtures record for an error, minus nulls.
fn describe(error: &VcsError) -> Value {
    let mut fields = Map::new();
    put(&mut fields, "_tag", error.tag());
    put(&mut fields, "message", error.to_string());
    let context = match error {
        VcsError::ProcessSpawn { context, .. }
        | VcsError::ProcessExit { context, .. }
        | VcsError::ProcessTimeout { context, .. }
        | VcsError::ProcessStdinWrite { context, .. }
        | VcsError::ProcessOutputRead { context, .. }
        | VcsError::ProcessOutputLimit { context, .. }
        | VcsError::ProcessMissingExitCode { context } => context,
        other => panic!("unexpected error {other:?}"),
    };
    put(&mut fields, "operation", context.operation.as_str());
    put(&mut fields, "command", context.command.as_str());
    put(&mut fields, "cwd", context.cwd.as_str());
    put(&mut fields, "argumentCount", context.argument_count);
    match error {
        VcsError::ProcessExit {
            exit_code,
            detail,
            failure_kind,
            retryable,
            stderr_length,
            stderr_truncated,
            ..
        } => {
            put(&mut fields, "exitCode", *exit_code);
            put(&mut fields, "detail", detail.as_str());
            put(
                &mut fields,
                "failureKind",
                failure_kind.map(|kind| kind.as_str()),
            );
            if *retryable {
                put(&mut fields, "retryable", true);
            }
            put(&mut fields, "stderrLength", *stderr_length);
            put(&mut fields, "stderrTruncated", *stderr_truncated);
        }
        VcsError::ProcessTimeout { timeout_ms, .. } => put(&mut fields, "timeoutMs", *timeout_ms),
        VcsError::ProcessStdinWrite { stdin_bytes, .. } => {
            put(&mut fields, "stdinBytes", *stdin_bytes)
        }
        VcsError::ProcessOutputRead { stream, .. } => put(&mut fields, "stream", stream.as_str()),
        VcsError::ProcessOutputLimit {
            stream,
            max_bytes,
            observed_bytes,
            ..
        } => {
            put(&mut fields, "stream", stream.as_str());
            put(&mut fields, "maxBytes", *max_bytes);
            put(&mut fields, "observedBytes", *observed_bytes);
        }
        _ => {}
    }
    Value::Object(fields)
}

fn without_nulls(value: &Value) -> Value {
    match value {
        Value::Object(map) => Value::Object(
            map.iter()
                .filter(|(_, value)| !value.is_null())
                .map(|(key, value)| (key.clone(), without_nulls(value)))
                .collect(),
        ),
        other => other.clone(),
    }
}

fn describe_output(output: &t3_vcs::VcsProcessOutput) -> Value {
    json!({
        "exitCode": output.exit_code,
        "stdout": output.stdout,
        "stderr": output.stderr,
        "stdoutTruncated": output.stdout_truncated,
        "stderrTruncated": output.stderr_truncated,
        "stdoutInvalidUtf8": output.stdout_invalid_utf8,
        "stderrInvalidUtf8": output.stderr_invalid_utf8,
    })
}

fn expected_result(row: &Value) -> Value {
    match (row["result"].get("ok"), row["result"].get("error")) {
        (Some(ok), _) => json!({ "ok": ok }),
        (_, Some(error)) => json!({ "error": without_nulls(error) }),
        _ => unreachable!(),
    }
}

async fn run(process: &VcsProcess, input: VcsProcessInput) -> Value {
    match process.run(input).await {
        Ok(output) => json!({ "ok": describe_output(&output) }),
        Err(error) => json!({ "error": describe(&error) }),
    }
}

fn output(code: Option<i32>, stderr: &str) -> ProcessRunOutput {
    ProcessRunOutput {
        code,
        stderr: stderr.into(),
        ..ProcessRunOutput::default()
    }
}

#[tokio::test]
async fn exit_classification_and_error_shapes_match_the_original() {
    let mut checked = 0;
    for line in include_str!("fixtures/vcs-process.jsonl").lines() {
        let row: Value = serde_json::from_str(line).unwrap();
        if row["type"] != "exit" {
            continue;
        }
        let stderr = row["stderr"].as_str().unwrap().to_string();
        let truncated = row["stderrTruncated"].as_bool().unwrap();
        let (process, _) = process_with(move |_| {
            Ok(ProcessRunOutput {
                stderr_truncated: truncated,
                ..output(Some(128), &stderr)
            })
        });
        let actual = run(&process, input(&row)).await;
        assert_eq!(actual, expected_result(&row), "{row}");
        checked += 1;
    }
    assert_eq!(checked, 380);
}

#[tokio::test]
async fn exit_code_boundaries_match_the_original() {
    let mut checked = 0;
    for line in include_str!("fixtures/vcs-process.jsonl").lines() {
        let row: Value = serde_json::from_str(line).unwrap();
        if row["type"] != "boundary" {
            continue;
        }
        let code = row["code"].as_i64().map(|code| code as i32);
        let (process, _) = process_with(move |_| {
            Ok(ProcessRunOutput {
                stdout: "out".into(),
                ..output(code, "err")
            })
        });
        let actual = run(&process, input(&row)).await;
        assert_eq!(actual, expected_result(&row), "{row}");
        checked += 1;
    }
    assert_eq!(checked, 8);
}

#[tokio::test]
async fn runner_failures_map_to_the_original_errors() {
    let mut checked = 0;
    for line in include_str!("fixtures/vcs-process.jsonl").lines() {
        let row: Value = serde_json::from_str(line).unwrap();
        if row["type"] != "runner-failure" {
            continue;
        }
        let io = || Arc::new(std::io::Error::other("cause"));
        let failure = match row["name"].as_str().unwrap() {
            "spawn" => ProcessRunError::Spawn(io()),
            "stdin" => ProcessRunError::Stdin {
                stdin_bytes: 47,
                cause: io(),
            },
            "output-limit-stdout" => ProcessRunError::OutputLimit {
                stream: OutputStream::Stdout,
                max_bytes: 128,
                observed_bytes: 2048,
            },
            "output-limit-stderr" => ProcessRunError::OutputLimit {
                stream: OutputStream::Stderr,
                max_bytes: 8,
                observed_bytes: 9,
            },
            "read-stdout" => ProcessRunError::Read {
                stream: ReadStream::Stdout,
                cause: io(),
            },
            "read-stderr" => ProcessRunError::Read {
                stream: ReadStream::Stderr,
                cause: io(),
            },
            "read-exit-code" => ProcessRunError::Read {
                stream: ReadStream::ExitCode,
                cause: io(),
            },
            "timeout" => ProcessRunError::Timeout { timeout_ms: 30_000 },
            other => panic!("unknown failure {other}"),
        };
        let (process, _) = process_with(move |_| Err(failure.clone()));
        let actual = run(&process, input(&row)).await;
        assert_eq!(actual, expected_result(&row), "{row}");
        checked += 1;
    }
    assert_eq!(checked, 8);
}

#[tokio::test]
async fn checkpoint_capture_retries_only_transient_git_failures() {
    let mut checked = 0;
    for line in include_str!("fixtures/vcs-process.jsonl").lines() {
        let row: Value = serde_json::from_str(line).unwrap();
        if row["type"] != "retry" {
            continue;
        }
        let failures = row["failures"].as_u64().unwrap() as usize;
        let stderr = row["stderr"].as_str().unwrap().to_string();
        let (process, runner) = process_with(move |attempt| {
            Ok(if attempt > failures {
                output(Some(0), "")
            } else {
                output(Some(attempt as i32), &stderr)
            })
        });
        let mut input = input(&row);
        assert_eq!(
            row["operation"] == CHECKPOINT_CAPTURE_OPERATION,
            input.operation == CHECKPOINT_CAPTURE_OPERATION
        );
        input.operation = row["operation"].as_str().unwrap().into();
        let actual = run(&process, input).await;
        assert_eq!(actual, expected_result(&row), "{row}");
        assert_eq!(
            runner.attempts.load(Ordering::SeqCst),
            row["attempts"].as_u64().unwrap() as usize,
            "{row}"
        );
        checked += 1;
    }
    assert_eq!(checked, 80);
}
